{"id":"80cf2689-994a-4687-992f-53486f1b1533","inserted_at":"2026-04-15T11:52:52.498192+00:00","updated_at":"2026-04-15T11:52:52.498192+00:00","type":"sql","name":"ESG Impact Tracking & POI Retrieval","description":"","content":{"sql":"-- 1. Estensione della tabella Profiles con i parametri ESG\r\nALTER TABLE public.profiles \r\nADD COLUMN IF NOT EXISTS total_tokens BIGINT DEFAULT 0,\r\nADD COLUMN IF NOT EXISTS total_co2 DECIMAL DEFAULT 0,\r\nADD COLUMN IF NOT EXISTS total_liters_water DECIMAL DEFAULT 0,\r\nADD COLUMN IF NOT EXISTS referral_code TEXT,\r\nADD COLUMN IF NOT EXISTS onboarding_completed BOOLEAN DEFAULT FALSE,\r\nADD COLUMN IF NOT EXISTS nickname TEXT,\r\nADD COLUMN IF NOT EXISTS party_size INTEGER DEFAULT 1;\r\n\r\n-- 2. Creazione tabella per la certificazione delle transazioni (Anti-Double-Spend)\r\nCREATE TABLE IF NOT EXISTS public.impact_transactions (\r\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\r\n    profile_id UUID REFERENCES public.profiles(id),\r\n    poi_id UUID,\r\n    receipt_hash TEXT UNIQUE, -- Impedisce lo scontrino duplicato\r\n    tokens_earned INTEGER,\r\n    co2_saved DECIMAL,\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\r\n);\r\n\r\n-- 3. Funzione RPC: process_esg_impact\r\n-- Gestisce l'erogazione di XP e Token con moltiplicatore Party Size\r\nCREATE OR REPLACE FUNCTION process_esg_impact(\r\n    user_id UUID,\r\n    p_co2 DECIMAL,\r\n    p_liters DECIMAL,\r\n    p_tokens INTEGER,\r\n    p_xp INTEGER,\r\n    p_takeaway BOOLEAN,\r\n    p_party_size INTEGER\r\n) RETURNS VOID AS $$\r\nBEGIN\r\n    UPDATE public.profiles\r\n    SET \r\n        total_co2 = total_co2 + p_co2,\r\n        total_liters_water = total_liters_water + p_liters,\r\n        total_tokens = total_tokens + p_tokens,\r\n        party_size = p_party_size\r\n    WHERE id = user_id;\r\n\r\n    -- Inserimento record transazione\r\n    INSERT INTO public.impact_transactions (profile_id, co2_saved, tokens_earned)\r\n    VALUES (user_id, p_co2, p_tokens);\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\n-- 4. Funzione RPC: get_pois_v4\r\nCREATE OR REPLACE FUNCTION get_pois_v4()\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    latitude DOUBLE PRECISION,\r\n    longitude DOUBLE PRECISION,\r\n    checkin_radius INTEGER,\r\n    has_refill BOOLEAN,\r\n    crowd_level INTEGER,\r\n    p_iva TEXT,\r\n    is_recommended BOOLEAN\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY SELECT \r\n        p.id, p.name, p.category, p.latitude, p.longitude, \r\n        p.checkin_radius, p.has_refill, p.crowd_level, p.p_iva, p.is_recommended\r\n    FROM pois p;\r\nEND;\r\n$$ LANGUAGE plpgsql;","content_id":"80cf2689-994a-4687-992f-53486f1b1533","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
